const fmt=n=>{if(!Number.isFinite(+n)||+n<0)return"--";const u=["B","KB","MB","GB","TB"];let v=+n,i=0;while(v>=1024&&i<u.length-1){v/=1024;i++}return v.toFixed(i?1:0)+" "+u[i]};
const rate=n=>fmt(n)+"/s",up=s=>{const d=Math.floor(s/86400),h=Math.floor(s%86400/3600);return d?d+"d "+h+"h":h+"h"};
function state(id,on){const e=$(id);if(e)e.style.color=on?"#28df86":"#e45d5d"}
function draw(){const c=$("chart"),r=c.getBoundingClientRect(),d=devicePixelRatio||1;c.width=r.width*d;c.height=r.height*d;const x=c.getContext("2d");x.scale(d,d);x.clearRect(0,0,r.width,r.height);x.strokeStyle="#172832";x.fillStyle="#617984";x.font="8px Segoe UI";for(let i=0;i<=4;i++){const y=r.height*i/4;x.beginPath();x.moveTo(0,y);x.lineTo(r.width,y);x.stroke();if(i<4)x.fillText((100-i*25)+"%",4,y+10)}[[hist.cpu,"#ffd21c"],[hist.ram,"#28df86"]].forEach(([a,col])=>{if(a.length<2)return;x.strokeStyle=col;x.lineWidth=2;x.beginPath();a.forEach((v,i)=>{const px=i/Math.max(59,a.length-1)*r.width,py=r.height-Math.min(100,v)/100*r.height;i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()})}
async function refresh(){document.querySelectorAll(".metric").forEach(e=>e.classList.add("loading"));try{const r=await fetch("/api/dashboard",{cache:"no-store"});if(!r.ok)throw Error("HTTP "+r.status);const d=await r.json();$("host").textContent=d.hostname;$("cpu").textContent=d.cpuPercent+"%";$("cpuBar").style.width=d.cpuPercent+"%";$("cores").textContent=d.cpuCount+" núcleos";$("ram").textContent=d.memory.percent+"%";$("ramBar").style.width=d.memory.percent+"%";$("ramtxt").textContent=fmt(d.memory.used)+" / "+fmt(d.memory.total);$("disk").textContent=d.disk.percent+"%";$("diskBar").style.width=d.disk.percent+"%";$("disktxt").textContent=fmt(d.disk.used)+" / "+fmt(d.disk.total);$("temp").textContent=d.temperature==null?"N/D":d.temperature+"°C";$("uptime").textContent=up(d.uptime);const ss=Object.values(d.services),online=d.pm2.filter(p=>p.status==="online").length;$("svc").textContent=ss.filter(Boolean).length+"/"+ss.length;$("pm2txt").textContent=online+"/"+d.pm2.length+" procesos PM2";$("loads").textContent=d.load.map(v=>v.toFixed(2)).join(" / ");$("netrate").textContent="↓ "+rate(d.network.rxPerSec)+" · ↑ "+rate(d.network.txPerSec);$("iface").textContent="interfaz "+(d.network.interface||"N/D");$("privateIp").textContent=d.network.privateIp||"N/D";$("publicIp").textContent=d.network.publicIp||"N/D";state("nginx",d.services.nginx);state("mysql",d.services.mysql);state("fail2ban",d.services.fail2ban);state("ddns",d.services.ddns);state("pm2status",d.pm2.some(p=>p.status==="online"));$("services").innerHTML=Object.entries(d.services).map(([n,on])=>`<div class="service-row"><i class="dot ${on?"":"off"}"></i><b>${({nginx:"Nginx",mysql:"MySQL",fail2ban:"Fail2ban",ddns:"Cloudflare DDNS"})[n]}</b><small>${on?"ACTIVO":"INACTIVO"}</small></div>`).join("");$("processes").innerHTML=d.pm2.map(p=>`<div class="service-row"><i class="dot ${p.status==="online"?"":"off"}"></i><div><b>${p.name}</b><span class="meta">CPU ${p.cpu}% · RAM ${fmt(p.memory)} · reinicios ${p.restarts}</span></div><small>${p.status.toUpperCase()}</small></div>`).join("")||'<div class="service-row"><small>PM2 sin datos</small></div>';hist.cpu.push(d.cpuPercent);hist.ram.push(d.memory.percent);if(hist.cpu.length>60){hist.cpu.shift();hist.ram.shift()}document.querySelectorAll(".metric").forEach(e=>e.classList.remove("loading"));$("connectionBanner").classList.remove("show");const healthy=d.health?.level==="ok";$("healthText").textContent=healthy?"SISTEMA ESTABLE":d.health?.level==="critical"?"ATENCIÓN CRÍTICA":"REVISAR SISTEMA";$("healthText").parentElement.classList.toggle("bad",!healthy);$("healthLevel").textContent=healthy?"ESTABLE":d.health?.level==="critical"?"CRÍTICO":"ADVERTENCIA";$("healthLevel").className=d.health?.level||"ok";$("healthDot").className=d.health?.level||"ok";$("healthSummary").textContent=d.health?.summary||"Estado no disponible";$("healthDetail").textContent=d.health?.issues?.length?d.health.issues.map(x=>x.text).join(" · "):"CPU, RAM, disco, PM2 y servicios base sin alertas";$("activity").innerHTML=[["CPU",d.cpuPercent+"%"],["RAM",d.memory.percent+"%"],["Red","↓ "+rate(d.network.rxPerSec)+" · ↑ "+rate(d.network.txPerSec)],["PM2",online+"/"+d.pm2.length+" online"]].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join("");$("lastUpdate").textContent="actualizado "+new Date().toLocaleTimeString("es-AR",{hour:"2-digit",minute:"2-digit",second:"2-digit"});draw()}catch(e){document.querySelectorAll(".metric").forEach(x=>x.classList.remove("loading"));$("connectionBanner").classList.add("show");$("healthText").textContent="SIN CONEXIÓN";$("healthText").parentElement.classList.add("bad");$("lastUpdate").textContent="error de conexión"}}
