const menu=$("mobileMenu"),sidebar=$("sidebar"),overlay=$("mobileOverlay");function closeMenu(){sidebar.classList.remove("open");overlay.classList.remove("show");menu?.setAttribute("aria-expanded","false")}menu?.setAttribute("aria-expanded","false");menu?.addEventListener("click",()=>{const open=!sidebar.classList.contains("open");sidebar.classList.toggle("open",open);overlay.classList.toggle("show",open);menu.setAttribute("aria-expanded",String(open))});overlay?.addEventListener("click",closeMenu);addEventListener("keydown",e=>{if(e.key==="Escape")closeMenu()});
let csrfToken="";fetch("/api/auth/session",{cache:"no-store"}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{csrfToken=d.csrf||"";$("sessionUser").textContent=(d.user||"admin").toUpperCase();$("recoveryLeft").textContent=d.recoveryCodesRemaining;$("sessionSince").textContent="desde "+new Date(d.loginAt).toLocaleString("es-AR")}).catch(()=>location.replace("/login"));$("logoutBtn")?.addEventListener("click",async()=>{if(!confirm("¿Cerrar la sesión del panel?"))return;const r=await fetch("/api/auth/logout",{method:"POST",headers:{"x-csrf-token":csrfToken}});if(r.ok)location.replace("/login")});$("poweroffBtn")?.addEventListener("click",async()=>{if(!confirm("¿APAGAR COMPLETAMENTE el servidor JR?\n\nSe detendrán la web, MySQL, PM2 y el panel hasta que vuelvas a encender físicamente el equipo."))return;if(!confirm("Última confirmación: ¿seguro que querés APAGAR el servidor?"))return;const b=$("poweroffBtn");b.disabled=true;b.textContent="APAGANDO...";try{const r=await fetch("/api/system/poweroff",{method:"POST",headers:{"x-csrf-token":csrfToken}});if(!r.ok)throw Error();setTimeout(()=>{$("connectionBanner").textContent="Servidor apagado · podés desconectar o trabajar en el hardware";$("connectionBanner").classList.add("show")},1200)}catch{b.disabled=false;b.textContent="APAGAR SERVER";alert("No se pudo apagar el servidor.")}});

const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));async function loadSecurity(){try{const [sr,hr]=await Promise.all([fetch("/api/auth/sessions",{cache:"no-store"}),fetch("/api/auth/history",{cache:"no-store"})]);if(!sr.ok||!hr.ok)throw Error();const s=await sr.json(),h=await hr.json();$("activeSessions").innerHTML=s.sessions.map(x=>`<div><b>${x.current?"● ACTUAL":"○ ACTIVA"}</b><span>${esc(x.ip)} · ${esc(x.device||x.agent).slice(0,70)}</span><small>${new Date(x.loginAt).toLocaleString("es-AR")}</small></div>`).join("")||"<p>Sin sesiones</p>";$("loginHistory").innerHTML=h.logins.slice(0,12).map(x=>`<div><b class="${x.success?"good":"bad"}">${x.success?"ACCESO CORRECTO":"FALLIDO"}</b><span>${esc(x.ip)} · ${esc(x.user)}</span><small>${new Date(x.time).toLocaleString("es-AR")}</small></div>`).join("")||"<p>Sin registros</p>";$("auditHistory").innerHTML=h.audit.slice(0,12).map(x=>`<div><b>${esc(x.action).toUpperCase()}</b><span>${esc(x.ip)} · ${esc(x.user)}</span><small>${new Date(x.time).toLocaleString("es-AR")}</small></div>`).join("")||"<p>Sin registros</p>"}catch{$("activeSessions").innerHTML="<p>No se pudo cargar la información.</p>"}}$("securityDetails")?.addEventListener("click",()=>{$("securityPanel").hidden=false;loadSecurity()});$("securityClose")?.addEventListener("click",()=>{$("securityPanel").hidden=true});$("logoutAllBtn")?.addEventListener("click",async()=>{if(!confirm("¿Cerrar TODAS las sesiones del panel? Vas a tener que iniciar sesión nuevamente."))return;const r=await fetch("/api/auth/logout-all",{method:"POST",headers:{"x-csrf-token":csrfToken}});if(r.ok)location.replace("/login")});

function showView(view){const ids={dashboard:"dashboardView",pm2:"pm2Panel",nginx:"nginxPanel",mysql:"mysqlPanel",backups:"backupPanel",ddns:"ddnsPanel",security:"systemSecurityPanel",ssl:"sslPanel",updates:"updatesPanel",gitdeploy:"gitDeployPanel",terminal:"terminalPanel",files:"filesPanel",editor:"editorPanel",logs:"logsPanel",alerts:"alertsPanel",storage:"storagePanel",opsV2:"opsV2Panel"};Object.entries(ids).forEach(([v,id])=>{const e=$(id);if(e)e.hidden=v!==view});document.querySelectorAll("#sidebar nav a").forEach(a=>a.classList.remove("on"));const navs={dashboard:"dashboardNav",pm2:"pm2Nav",nginx:"nginxNav",mysql:"mysqlNav",backups:"backupNav",ddns:"ddnsNav",security:"systemSecurityNav",ssl:"sslNav",updates:"updatesNav",gitdeploy:"gitDeployNav",terminal:"terminalNav",files:"filesNav",editor:"editorNav",logs:"logsNav",alerts:"alertsNav",storage:"storageNav",opsV2:"opsV2Nav"};$(navs[view]||"dashboardNav")?.classList.add("on");scrollTo({top:0,behavior:"smooth"});closeMenu()}
