const pm2Time=t=>t?new Date(t).toLocaleString("es-AR"):"--";
async function loadPm2Panel(){if(pm2Busy)return;pm2Busy=true;try{const r=await fetch("/api/pm2",{cache:"no-store"});if(r.status===401)return location.replace("/login");if(!r.ok)throw Error();const d=await r.json();$("pm2Cards").innerHTML=d.processes.map(p=>`<article class="pm2-card"><div class="pm2-card-head"><div><i class="dot ${p.status==="online"?"":"off"}"></i><strong>${esc(p.name)}</strong></div><span class="${p.status==="online"?"good":"bad"}">${esc(p.status).toUpperCase()}</span></div><div class="pm2-stats"><div><small>CPU</small><b>${p.cpu}%</b></div><div><small>RAM</small><b>${fmt(p.memory)}</b></div><div><small>PID</small><b>${p.pid??"--"}</b></div><div><small>REINICIOS</small><b>${p.restarts}</b></div></div><div class="pm2-meta"><span>Inicio: ${pm2Time(p.uptime)}</span><span>Node: ${esc(p.nodeVersion||"--")}</span><span>Modo: ${esc(p.execMode||"--")}</span><span>ID PM2: ${p.id??"--"}</span></div><div class="pm2-actions"><button data-log="${esc(p.name)}">VER LOGS</button><button data-act="restart" data-name="${esc(p.name)}">REINICIAR</button>${p.status==="online"?`<button class="danger" data-act="stop" data-name="${esc(p.name)}">DETENER</button>`:`<button class="start" data-act="start" data-name="${esc(p.name)}">INICIAR</button>`}</div></article>`).join("")||"<p>No hay procesos PM2.</p>"}catch{$("pm2Cards").innerHTML="<p>No se pudo obtener el estado de PM2.</p>"}finally{pm2Busy=false}}
async function pm2Logs(name){$("pm2LogTitle").textContent="Logs · "+name;$("pm2Logs").textContent="Cargando...";try{const r=await fetch("/api/pm2/"+encodeURIComponent(name)+"/logs",{cache:"no-store"});const d=await r.json();$("pm2Logs").textContent=r.ok?(d.lines.join("\n")||"Sin líneas recientes."):"No se pudieron cargar los logs."}catch{$("pm2Logs").textContent="Error al consultar logs."}}
async function pm2Action(name,action){const labels={restart:"REINICIAR",stop:"DETENER",start:"INICIAR"};if(!confirm("¿"+labels[action]+" el proceso PM2 "+name+"?"))return;const r=await fetch("/api/pm2/"+encodeURIComponent(name)+"/"+action,{method:"POST",headers:{"x-csrf-token":csrfToken}});if(r.status===401)return location.replace("/login");if(!r.ok){alert("No se pudo ejecutar la acción en PM2.");return}await loadPm2Panel();setTimeout(loadPm2Panel,1200)}
