async function loadMysql(){try{const r=await fetch("/api/mysql",{cache:"no-store"});if(r.status===401)return location.replace("/login");const d=await r.json();if(!r.ok)throw Error();$("mysqlState").textContent=d.active?"ACTIVO":"INACTIVO";$("mysqlState").className=d.active?"good":"bad";$("mysqlVersion").textContent=d.version;$("mysqlUptime").textContent=durationSec(d.stats.Uptime);$("mysqlThreads").textContent=(d.stats.Threads_connected||0)+" / "+(d.stats.Threads_running||0)+" ejecutando";$("mysqlQuestions").textContent=(d.stats.Questions||0).toLocaleString("es-AR");$("mysqlConnections").textContent=(d.stats.Connections||0).toLocaleString("es-AR");$("mysqlDatabases").innerHTML=d.databases.map(x=>`<article><small>${x.name==="jr_electricidad"?"PRODUCCIÓN":"PRUEBAS"}</small><strong>${esc(x.name)}</strong><span>${x.sizeMB.toFixed(2)} MB · ${x.tables} tablas</span></article>`).join("")||"<p>No se detectaron las bases JR.</p>"}catch{$("mysqlDatabases").innerHTML="<p>No se pudo consultar MySQL.</p>"}}
