function fmtBytes(n){n=Number(n)||0;if(n<1024)return n+" B";const u=["KB","MB","GB","TB"];let i=-1;do{n/=1024;i++}while(n>=1024&&i<u.length-1);return n.toFixed(n>=10?1:2)+" "+u[i]}
function backupAge(iso){if(!iso)return"--";const ms=Date.now()-new Date(iso).getTime(),h=Math.max(0,Math.floor(ms/3600000));return h<24?"hace "+h+" h":"hace "+Math.floor(h/24)+" d"}
async function loadDdns(){try{const r=await fetch("/api/ddns",{cache:"no-store"});if(!r.ok)throw Error("HTTP "+r.status);const d=await r.json();$("ddnsTimer").textContent=d.timerActive?"ACTIVO":"INACTIVO";$("ddnsTimer").className=d.timerActive?"good":"bad";$("ddnsTimerMeta").textContent=(d.timerEnabled?"habilitado":"no habilitado")+" · "+(d.serviceState||"desconocido");$("ddnsLast").textContent=d.lastRun||"Sin datos";$("ddnsResult").textContent=d.lastResult||"Sin datos";$("ddnsNext").textContent=d.nextRun||"Sin datos";$("ddnsPublicIp").textContent=d.publicIp||"N/D";$("ddnsRecords").innerHTML=(d.records||[]).map(x=>`<div><b>${esc(x)}</b><span>ADMINISTRADO</span></div>`).join("")||"<div><b>Sin registros informados</b></div>";$("ddnsLogs").textContent=(d.logs||[]).join("\n")||"Sin actividad reciente."}catch(e){$("ddnsTimer").textContent="ERROR";$("ddnsTimer").className="bad";$("ddnsTimerMeta").textContent="no se pudo consultar";$("ddnsRecords").textContent="No se pudieron cargar los registros.";$("ddnsLogs").textContent="Error al cargar Cloudflare / DDNS: "+e.message}}
async function runDdns(){const b=$("ddnsRun"),out=$("ddnsOutput");b.disabled=true;out.textContent="Ejecutando comprobación DDNS...";try{const r=await fetch("/api/ddns/run",{method:"POST",headers:{"x-csrf-token":csrfToken}}),d=await r.json();if(!r.ok)throw Error(d.output||d.error||("HTTP "+r.status));out.textContent=d.output||"Comprobación DDNS ejecutada correctamente.";await loadDdns()}catch(e){out.textContent="ERROR: "+e.message}finally{b.disabled=false}}
async function loadBackups(){try{const r=await fetch("/api/backups",{cache:"no-store"});if(r.status===401)return location.replace("/login");const d=await r.json();if(!r.ok)throw Error();$("backupCount").textContent=d.totalFiles.toLocaleString("es-AR");$("backupSize").textContent=fmtBytes(d.totalBytes);$("backupLast").textContent=d.last?new Date(d.last.mtime).toLocaleString("es-AR"):"SIN BACKUPS";$("backupLastAge").textContent=d.last?backupAge(d.last.mtime):"No se encontraron archivos";$("backupScript").textContent=d.script.exists?"LISTO":"NO DISPONIBLE";$("backupScript").className=d.script.exists?"good":"bad";$("backupScriptMeta").textContent=d.script.exists?"modo "+d.script.mode+" · "+d.script.owner:"backup-jr.sh no encontrado";$("backupRows").innerHTML=d.files.length?d.files.map(x=>`<tr><td title="${esc(x.path)}">${esc(x.name)}</td><td>${x.kind==="database"?"BASE DE DATOS":x.kind==="archive"?"ARCHIVO":"OTRO"}</td><td>${new Date(x.mtime).toLocaleString("es-AR")}</td><td>${fmtBytes(x.size)}</td></tr>`).join(""):'<tr><td colspan="4">No se encontraron respaldos.</td></tr>'}catch{$("backupRows").innerHTML='<tr><td colspan="4">No se pudo consultar backups.</td></tr>'}}
