const gitNames={panel:"JR Server Panel",prod:"JR Electricidad",test:"JR Electricidad Pruebas"};const gitEnvs={panel:"PANEL · PRODUCCIÓN",prod:"SITIO · PRODUCCIÓN",test:"ENTORNO · PRUEBAS"};const gitPm2Labels={panel:"Panel",prod:"Producción",test:"Pruebas"};
async function loadGitDeploy(){try{const r=await fetch("/api/git-deploy",{cache:"no-store"});if(r.status===401)return location.replace("/login");const d=await r.json();if(!r.ok)throw Error();$("gitDeployCards").innerHTML=d.projects.map(p=>{const synced=p.ahead===0&&p.behind===0,deployable=p.clean&&p.ahead===0;return `<article class="git-deploy-card"><div class="git-deploy-head"><div><small>${esc(gitEnvs[p.project]||"REPOSITORIO")}</small><strong>${esc(gitNames[p.project]||p.project)}</strong></div><span class="${p.clean?"good":"warn"}">${p.clean?"LIMPIO":"CAMBIOS LOCALES"}</span></div><div class="git-deploy-meta"><div><small>RAMA GIT</small><b>${esc(p.branch)}</b></div><div><small>SINCRONIZACIÓN</small><b class="${synced?"good":"warn"}">↓ ${p.behind} · ↑ ${p.ahead}</b></div><div><small>PROCESO</small><b title="${esc(p.pm2)}">${esc(gitPm2Labels[p.project]||p.pm2)}</b></div></div><p>${esc(p.lastCommit)}</p>${p.changes.length?`<pre>${p.changes.map(esc).join("\n")}</pre>`:""}<div class="git-deploy-actions"><button data-git-log="${p.project}">COMMITS</button><button data-git-diff="${p.project}">VER DIFF</button>${p.project==="panel"?'<span class="git-deploy-manual">DEPLOY MANUAL</span>':`<button data-git-deploy="${p.project}" ${deployable?"":"disabled"}>DEPLOY</button>`}</div></article>`}).join("")}catch{$("gitDeployCards").innerHTML="<p>No se pudo consultar Git / Deploy.</p>"}}
async function gitDetail(project,type){const out=$(type==="log"?"gitDeployLog":"gitDeployDiff"),title=$(type==="log"?"gitDeployLogTitle":"gitDeployDiffTitle");title.textContent=gitNames[project]||project;out.textContent="Cargando...";try{const r=await fetch("/api/git-deploy/"+project+"/"+type,{cache:"no-store"}),d=await r.json();out.textContent=r.ok?(type==="log"?(d.lines.join("\n")||"Sin commits."):(d.output||"Repositorio limpio. Sin cambios locales.")):"No disponible."}catch{out.textContent="No se pudo consultar."}}
