$("filesTrashView")?.addEventListener("dblclick",async()=>{if(!filesTrashMode||!filesSelected)return;const destination=prompt("Restaurar en:","/home/jorge");if(!destination)return;try{await filesPost("/api/files/restore",{trashName:filesSelected.trashName,name:filesSelected.originalName,destination});filesTrashMode=false;await filesLoad(destination);alert("Elemento restaurado.")}catch(e){alert("No se pudo restaurar: "+e.message)}});$("filesRows")?.addEventListener("dblclick",async e=>{if(!filesTrashMode)return;const tr=e.target.closest("[data-files-index]");if(!tr)return;const x=$("filesRows")._items[+tr.dataset.filesIndex];const destination=prompt("Restaurar "+x.originalName+" en:","/home/jorge");if(!destination)return;try{await filesPost("/api/files/restore",{trashName:x.trashName,name:x.originalName,destination});filesTrashMode=false;await filesLoad(destination);alert("Elemento restaurado correctamente.")}catch(err){alert("No se pudo restaurar: "+err.message)}});

function filesChosen(){const items=$("filesRows")?._items||[];return [...filesSelectedMany].map(i=>items[i]).filter(Boolean)}
function filesSyncSelection(){const n=filesSelectedMany.size;$("filesSelectAll").checked=!!n&&n===($("filesRows")?._items?.length||0);if(n>1)$("filesMeta").innerHTML=`<div><small>SELECCIÓN</small><b>${n} elementos</b></div>`}
$("filesSelectAll")?.addEventListener("change",e=>{filesSelectedMany.clear();const items=$("filesRows")?._items||[];if(e.target.checked)items.forEach((_,i)=>filesSelectedMany.add(i));document.querySelectorAll(".files-check").forEach(c=>c.checked=e.target.checked);filesSyncSelection()});
$("filesRows")?.addEventListener("change",e=>{const c=e.target.closest("[data-files-check]");if(!c)return;const i=+c.dataset.filesCheck;c.checked?filesSelectedMany.add(i):filesSelectedMany.delete(i);filesSyncSelection()});
$("filesRestore")?.addEventListener("click",async()=>{if(!filesTrashMode||!filesSelected)return alert("Seleccioná un elemento de la papelera.");const destination=prompt("Restaurar "+(filesSelected.originalName||filesSelected.name)+" en:","/home/jorge");if(!destination)return;try{await filesPost("/api/files/restore",{trashName:filesSelected.trashName,name:filesSelected.originalName,destination});$("filesRestore").hidden=true;filesTrashMode=false;await filesLoad(destination);alert("Elemento restaurado correctamente.")}catch(e){alert("No se pudo restaurar: "+e.message)}});

/* Fase 2 · Editor */
let editorCurrent="",editorDirty=false;
async function editorOpen(pathValue){const p=String(pathValue||$("editorPath").value||"").trim();if(!p)return alert("Indicá un archivo.");try{const r=await fetch("/api/editor/read?path="+encodeURIComponent(p),{cache:"no-store"}),d=await r.json();if(!r.ok)throw Error(d.error||"open_failed");editorCurrent=d.path;$("editorPath").value=d.path;$("editorArea").value=d.content;editorDirty=false;$("editorState").textContent="ABIERTO · "+fmt(d.size)}catch(e){alert("No se pudo abrir: "+e.message)}}
async function editorSave(){if(!editorCurrent)return alert("Abrí un archivo primero.");try{const d=await filesPost("/api/editor/save",{path:editorCurrent,content:$("editorArea").value});editorDirty=false;$("editorState").textContent="GUARDADO · "+new Date(d.modified).toLocaleTimeString("es-AR");}catch(e){alert("No se pudo guardar: "+e.message)}}
$("editorNav")?.addEventListener("click",()=>showView("editor"));$("editorClose")?.addEventListener("click",()=>showView("dashboard"));$("editorOpen")?.addEventListener("click",()=>editorOpen());$("editorSave")?.addEventListener("click",editorSave);$("editorArea")?.addEventListener("input",()=>{editorDirty=true;$("editorState").textContent="CAMBIOS SIN GUARDAR"});$("editorArea")?.addEventListener("keydown",e=>{if(e.key==="Tab"){e.preventDefault();const a=e.target,p=a.selectionStart,q=a.selectionEnd;a.value=a.value.slice(0,p)+"  "+a.value.slice(q);a.selectionStart=a.selectionEnd=p+2;editorDirty=true}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="s"){e.preventDefault();editorSave()}});

/* Fase 3 · Logs centralizados */
const logLine=x=>typeof x==="string"?x:JSON.stringify(x);
async function loadCentralLogs(){try{const r=await fetch("/api/logs/central",{cache:"no-store"}),d=await r.json();if(!r.ok)throw Error(d.error||"logs_unavailable");$("logsAudit").textContent=d.audit.map(logLine).join("\n")||"Sin eventos.";$("logsLogin").textContent=d.logins.map(logLine).join("\n")||"Sin accesos registrados.";$("logsNginx").textContent=d.nginx.join("\n")||"Sin errores recientes.";$("logsPm2").textContent=Object.entries(d.pm2).map(([n,lines])=>"=== "+n+" ===\n"+lines.join("\n")).join("\n\n")||"Sin logs PM2."}catch(e){["logsAudit","logsLogin","logsNginx","logsPm2"].forEach(id=>$(id).textContent="Error: "+e.message)}}
$("logsNav")?.addEventListener("click",()=>{showView("logs");loadCentralLogs()});$("logsRefresh")?.addEventListener("click",loadCentralLogs);$("logsClose")?.addEventListener("click",()=>showView("dashboard"));
/* Fase 4 · Alertas */
async function loadAlerts(){try{const r=await fetch("/api/alerts",{cache:"no-store"}),d=await r.json();if(!r.ok)throw Error(d.error||"alerts_unavailable");$("alertsList").innerHTML=d.alerts.length?d.alerts.map(a=>`<div class="alert-card ${a.level==="critical"?"bad":"warn"}"><b>${esc(a.title)}</b><span>${esc(a.detail)}</span></div>`).join(""):'<div class="alert-card"><b>✓ Sin alertas activas</b><span>Los indicadores vigilados están dentro de los umbrales definidos.</span></div>';const backup=d.backupAgeHours==null?"N/D":d.backupAgeHours+" h";$("alertsStats").innerHTML=`<div class="alert-card"><b>Disco · ${d.diskPercent}%</b><span>Aviso desde 80% · crítico desde 90%</span></div><div class="alert-card"><b>RAM · ${d.memoryPercent}%</b><span>Aviso desde 80% · crítico desde 90%</span></div><div class="alert-card"><b>Accesos fallidos · ${d.failedLogins24h}</b><span>Últimas 24 horas</span></div><div class="alert-card"><b>Nginx · ${d.nginxActive?"ACTIVO":"CAÍDO"}</b><span>Servicio web</span></div><div class="alert-card"><b>MySQL · ${d.mysqlActive?"ACTIVO":"CAÍDO"}</b><span>Base de datos</span></div><div class="alert-card"><b>Backup · ${backup}</b><span>Edad del último respaldo</span></div><div class="alert-card"><b>Seguridad · ${d.securityUpdates} pendiente(s)</b><span>Actualizaciones de seguridad</span></div><div class="alert-card"><b>Reinicio · ${d.rebootRequired?"PENDIENTE":"NO"}</b><span>Requerido por actualizaciones</span></div>`}catch(e){$("alertsList").textContent="Error: "+e.message}}
$("alertsNav")?.addEventListener("click",()=>{showView("alerts");loadAlerts()});$("alertsRefresh")?.addEventListener("click",loadAlerts);$("alertsClose")?.addEventListener("click",()=>showView("dashboard"));

$("filesEdit")?.addEventListener("click",()=>{if(filesSelectedMany.size>1)return alert("El editor abre un archivo por vez.");if(!filesSelected)return alert("Seleccioná un archivo.");if(filesSelected.type!=="file")return alert("Seleccioná un archivo de texto o código.");const p=filesSelected._searchPath||filesJoin(filesPath,filesSelected.name);showView("editor");editorOpen(p)});

/* Fases 5-9 · Dashboard, almacenamiento, backups, seguridad y sesiones */
async function loadStorageV2(){try{const r=await fetch("/api/storage",{cache:"no-store"}),d=await r.json();if(!r.ok)throw Error(d.error);const sys=d.disks?.system||d.disk,pro=d.disks?.projects;$("storageSummary").innerHTML=`<article><small>SISTEMA /</small><strong>${sys.percent}%</strong><span>${fmt(sys.used)} usados · ${fmt(sys.free)} libres · ${fmt(sys.total)} total</span></article>${pro?`<article><small>PROYECTOS /srv/proyectos</small><strong>${pro.percent}%</strong><span>${fmt(pro.used)} usados · ${fmt(pro.free)} libres · ${fmt(pro.total)} total</span></article>`:""}<article><small>RESERVA LVM</small><strong>${d.lvmReserve==null?"N/D":fmt(d.lvmReserve)}</strong><span>sin asignar en ubuntu-vg</span></article><article><small>RASTREADO</small><strong>${fmt(d.totalTracked)}</strong><span>ubicaciones JR</span></article>`;const labels={good:["BUENO","good"],warning:["ATENCIÓN","warn"],critical:["PROBLEMA","bad"],unknown:["SIN DATOS",""]};$("diskHealthRows").innerHTML=(d.health||[]).map(x=>{const l=labels[x.status]||labels.unknown;return `<article class="disk-health-card"><div><small>${esc(x.device)}</small><b>${esc(x.model||"Disco")}</b><span>${x.bytes?fmt(x.bytes):"Capacidad N/D"}${x.temperature!=null?" · "+x.temperature+" °C":""}</span><span>Horas: ${x.powerOnHours==null?"N/D":Number(x.powerOnHours).toLocaleString("es-AR")+" h"} · Reasignados: ${x.reallocated??"N/D"} · Pendientes: ${x.pending??"N/D"} · No corregibles: ${x.uncorrectable??"N/D"}</span></div><strong class="${l[1]}">● ${l[0]}</strong></article>`}).join("")||'<div class="disk-health-empty">SMART no disponible todavía.</div>';$("storageRows").innerHTML=d.locations.map(x=>`<div><b>${esc(x.name)}</b><span>${esc(x.path)}</span><strong>${fmt(x.bytes)}</strong></div>`).join("")}catch(e){$("storageRows").textContent="Error al cargar almacenamiento.";$("diskHealthRows").textContent="No se pudo consultar la salud de los discos."}}
$("storageNav")?.addEventListener("click",()=>{showView("storage");loadStorageV2()});$("storageRefresh")?.addEventListener("click",loadStorageV2);$("storageClose")?.addEventListener("click",()=>showView("dashboard"));
async function loadDashboardV2(){try{const [a,b,sr,st]=await Promise.all([fetch("/api/alerts",{cache:"no-store"}).then(r=>r.json()),fetch("/api/backups/v2",{cache:"no-store"}).then(r=>r.json()),fetch("/api/security/v2",{cache:"no-store"}).then(r=>r.json()),fetch("/api/storage",{cache:"no-store"}).then(r=>r.json())]);$("dashV2Alerts").textContent=a.alerts?.length||0;$("dashV2AlertMeta").textContent=a.alerts?.length?"requieren revisión":"sin alertas activas";$("dashV2Backup").textContent=b.healthy?"OK":"REVISAR";$("dashV2Backup").className=b.healthy?"good":"bad";$("dashV2BackupMeta").textContent=b.ageHours==null?"sin backup":"hace "+b.ageHours+" h";$("dashV2Sessions").textContent=sr.sessions??"--";$("dashV2Storage").textContent=(st.disk?.percent??"--")+"%";$("dashV2StorageMeta").textContent=fmt(st.disk?.free)+" libres"}catch{}}
