/* Fases 10-22 · Centro Sistema V2 */
const v2EscLines=a=>(a||[]).map(x=>"<div class=\"ops-line\">"+esc(typeof x==="string"?x:JSON.stringify(x))+"</div>").join("");
async function v2Json(url){const r=await fetch(url,{cache:"no-store"}),d=await r.json();if(!r.ok)throw Error(d.error||"unavailable");return d}
async function loadOpsV2(tab="diagnostics"){const c=$("opsV2Content"),t=$("opsV2Title"),st=$("opsV2State");st.textContent="CARGANDO";c.textContent="Consultando servidor...";try{let d;switch(tab){
case"updates":showView("updates");loadUpdates();return;
case"git":showView("gitDeploy");loadGitDeploy();return;
case"terminal":showView("terminal");openTerminal();return;
case"systemd":d=await v2Json("/api/systemd/v2");t.textContent="SYSTEMD · SERVICIOS";c.innerHTML=d.services.map(x=>`<div class="ops-card"><b>${esc(x.name)}</b><strong class="${x.active?"ok":"bad"}">${x.active?"ACTIVO":"INACTIVO"}</strong><span>${esc(x.enabled)}</span></div>`).join("");break;
case"processes":d=await v2Json("/api/processes/v2");t.textContent="PROCESOS LINUX";c.innerHTML="<pre>"+esc(d.lines.join("\n"))+"</pre>";break;
case"network":d=await v2Json("/api/network/v2");t.textContent="RED V2";{const lines=d.bandwidth?.lines||[],iface=d.interface||((lines.find(x=>/^interface=/i.test(x))||"").split("=")[1])||"N/D",active=d.bandwidth?.active||lines.some(x=>/^active=yes$/i.test(x.trim())),q=(lines.find(x=>/qdisc tbf/i.test(x))||""),m=q.match(/rate\s+([0-9.]+)([KMG])bit/i),mult=m?({K:.001,M:1,G:1000}[m[2].toUpperCase()]||1):1,current=m?Math.round(Number(m[1])*mult):null,link=d.link||{};c.innerHTML=`<div class="jr-speed jr-speed-pro"><div class="jr-speed-head"><div><small>JR NETWORK TEST · OOKLA ENGINE</small><h3>RENDIMIENTO DE INTERNET</h3></div><span class="jr-speed-dot">● LISTO</span></div><div class="jr-dual-gauges"><section class="jr-meter download"><div class="jr-meter-title">↓ DESCARGA</div><div class="jr-dial"><div class="jr-arc"></div><div class="jr-ticks"><i style="--p:0">0</i><i style="--p:1">10</i><i style="--p:2">20</i><i style="--p:3">50</i><i style="--p:4">100</i><i style="--p:5">200</i><i style="--p:6">300</i><i style="--p:7">500</i><i style="--p:8">750</i><i style="--p:9">1000</i></div><div class="jr-needle" id="netDownNeedle"></div><div class="jr-hub">↓</div><div class="jr-meter-value"><strong id="netDownload">--</strong><span>Mbps</span></div></div></section><section class="jr-meter upload"><div class="jr-meter-title">↑ SUBIDA</div><div class="jr-dial"><div class="jr-arc"></div><div class="jr-ticks"><i style="--p:0">0</i><i style="--p:1">10</i><i style="--p:2">20</i><i style="--p:3">50</i><i style="--p:4">100</i><i style="--p:5">200</i><i style="--p:6">300</i><i style="--p:7">500</i><i style="--p:8">750</i><i style="--p:9">1000</i></div><div class="jr-needle" id="netUpNeedle"></div><div class="jr-hub">↑</div><div class="jr-meter-value"><strong id="netUpload">--</strong><span>Mbps</span></div></div></section></div><div class="jr-quality"><div><small>PING</small><strong id="netPing">--</strong><span>ms</span></div><div><small>JITTER</small><strong id="netJitter">--</strong><span>ms</span></div><div><small>LATENCIA ↓</small><strong id="netDownLatency">--</strong><span>ms</span></div><div><small>LATENCIA ↑</small><strong id="netUpLatency">--</strong><span>ms</span></div></div><div class="jr-connection-card"><div><small>PROVEEDOR</small><b id="netIsp">--</b></div><div><small>SERVIDOR DE PRUEBA</small><b id="netServer">--</b></div><div><small>UBICACIÓN</small><b id="netLocation">--</b></div><div><small>IP PÚBLICA</small><b>${esc(d.publicIp||"N/D")}</b></div><div><small>INTERFAZ</small><b>${esc(iface)}</b></div><div><small>ENLACE</small><b>${link.speedMbps?link.speedMbps+" Mbps":"N/D"}</b></div></div><button class="jr-speed-start" data-net-speedtest="1">▶ INICIAR MEDICIÓN</button><div class="jr-speed-foot"><span>Motor oficial Ookla Speedtest CLI</span><span>${link.carrier===true?"● ENLACE ACTIVO":"○ SIN ENLACE"}</span></div></div><div class="jr-net-summary"><div class="ops-card"><b>Interfaz principal</b><strong>${esc(iface)}</strong><span>${active?`LÍMITE ACTIVO${current?" · "+current+" Mbps":""}`:"SIN LÍMITE"}</span></div><div class="ops-card"><b>Enlace de placa</b><strong>${link.speedMbps?link.speedMbps+" Mbps":"N/D"}</strong><span>${esc(link.duplex?link.duplex.toUpperCase():"")} ${link.carrier===true?"· CONECTADA":link.carrier===false?"· SIN ENLACE":""}</span></div></div><h4>Control de ancho de banda · salida</h4><div class="ops-quick"><button data-net-limit="5">5 MBPS</button><button data-net-limit="10">10 MBPS</button><button data-net-limit="20">20 MBPS</button><button data-net-limit="50">50 MBPS</button><button data-net-custom="1">PERSONALIZADO</button><button data-net-clear="1">QUITAR LÍMITE</button></div><div class="v2-notice">La medición ejecuta una prueba real y consume ancho de banda. El enlace de placa es la velocidad negociada con el router/switch. El limitador actual actúa sobre la salida mediante Linux tc.</div><h4>Estado del límite</h4>${v2EscLines(lines)}<h4>Interfaces</h4>${v2EscLines(d.addresses)}<h4>Rutas</h4>${v2EscLines(d.routes)}<h4>Puertos escuchando</h4>${v2EscLines(d.listening)}`;}break;
case"mysql":d=await v2Json("/api/mysql/v2");t.textContent="MYSQL V2";c.innerHTML=`<div class="ops-card"><b>Versión</b><strong>${esc(d.version||"N/D")}</strong></div><h4>Bases de datos</h4>${d.databases.map(x=>`<div class="ops-line">${esc(x.name)} · ${x.sizeMB} MB · ${x.tables} tablas</div>`).join("")}<h4>Procesos</h4>${v2EscLines(d.processes)}`;break;
case"schedules":d=await v2Json("/api/schedules/v2");t.textContent="CRON + TIMERS";c.innerHTML="<h4>systemd timers</h4>"+v2EscLines(d.timers)+"<h4>crontab de jorge</h4>"+(v2EscLines(d.cron)||'<div class="ops-line">Sin tareas cron.</div>');break;
case"timeline":d=await v2Json("/api/timeline/v2");t.textContent="TIMELINE GENERAL";c.innerHTML=d.events.map(x=>`<div class="ops-event"><time>${esc(new Date(x.time).toLocaleString("es-AR"))}</time><b>${esc(x.action||"evento")}</b><span>${esc(x.target||x.user||x.ip||"")}</span></div>`).join("")||"Sin eventos.";break;
case"diagnostics":d=await v2Json("/api/diagnostics/v2");t.textContent="DIAGNÓSTICO AUTOMÁTICO";c.innerHTML=d.checks.map(x=>`<div class="ops-card"><b>${esc(x.name)}</b><strong class="${x.ok?"ok":"bad"}">${x.ok?"OK":"REVISAR"}</strong><span>${esc(x.detail||"")}</span></div>`).join("");break;
case"quick":t.textContent="ACCIONES RÁPIDAS";c.innerHTML='<div class="ops-quick"><button data-go="pm2">PM2</button><button data-go="backup">BACKUP</button><button data-go="ddns">DDNS</button><button data-go="ssl">SSL</button><button data-go="updates">ACTUALIZACIONES</button><button data-go="files">ARCHIVOS</button><button data-go="terminal">TERMINAL</button></div>';break;
case"settings":d=await v2Json("/api/settings/v2");t.textContent="AJUSTES V2";c.innerHTML=Object.entries(d).map(([k,v])=>`<div class="ops-card"><b>${esc(k)}</b><strong>${esc(String(v))}</strong></div>`).join("");break;
case"servers":d=await v2Json("/api/servers/v2");t.textContent="PREPARACIÓN MULTI-SERVIDOR";c.innerHTML=d.servers.map(x=>`<div class="ops-card"><b>${esc(x.name)}</b><strong class="ok">${x.online?"ONLINE":"OFFLINE"}</strong><span>${esc(x.host+" · "+x.platform+" "+x.release)}</span></div>`).join("")+'<div class="v2-notice">Arquitectura preparada para incorporar más servidores sin habilitar conexiones remotas todavía.</div>';break;
default:return loadOpsV2("diagnostics")}st.textContent="LISTO"}catch(e){st.textContent="ERROR";c.textContent="No se pudo cargar esta fase: "+e.message}}
$("opsV2Nav")?.addEventListener("click",()=>{showView("opsV2");loadOpsV2("diagnostics")});$("opsV2Refresh")?.addEventListener("click",()=>loadOpsV2(document.querySelector(".ops-tabs button.on")?.dataset.v2tab||"diagnostics"));$("opsV2Close")?.addEventListener("click",()=>showView("dashboard"));document.querySelectorAll("[data-v2tab]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("[data-v2tab]").forEach(x=>x.classList.remove("on"));b.classList.add("on");loadOpsV2(b.dataset.v2tab)}));$("opsV2Content")?.addEventListener("click",e=>{const b=e.target.closest("[data-go]");if(!b)return;const map={pm2:"pm2Nav",backup:"backupNav",ddns:"ddnsNav",ssl:"sslNav",updates:"updatesNav",files:"filesNav",terminal:"terminalNav"};$(map[b.dataset.go])?.click()});$("opsV2Content")?.addEventListener("click",async e=>{const b=e.target.closest("[data-net-speedtest]");if(!b)return;const ping=$("netPing"),down=$("netDownload"),up=$("netUpload"),dn=$("netDownNeedle"),un=$("netUpNeedle"),state=document.querySelector(".jr-speed-dot"),setNeedle=(el,v)=>{if(!el)return;const n=Math.max(0,Number(v)||0),max=n>1000?Math.ceil(n/500)*500:1000,ratio=Math.min(1,n/max);el.style.transform="rotate("+(-120+ratio*240)+"deg)"};b.disabled=true;b.textContent="MIDIENDO...";if(state){state.textContent="● MIDIENDO";state.classList.add("measuring")}document.querySelector(".jr-speed-pro")?.classList.add("is-testing");dn?.classList.add("sweeping");un?.classList.add("waiting");try{const r=await fetch("/api/network/speedtest",{method:"POST",headers:{"content-type":"application/json","x-csrf-token":csrfToken},body:"{}"}),d=await r.json();if(!r.ok)throw Error(d.detail||d.error||"speedtest_failed");dn?.classList.remove("sweeping");un?.classList.remove("waiting");if(dn)setNeedle(dn,d.downloadMbps);if(un)setNeedle(un,d.uploadMbps);if(ping)ping.textContent=d.pingMs;if(down)down.textContent=d.downloadMbps;if(up)up.textContent=d.uploadMbps;const jitter=$("netJitter"),dl=$("netDownLatency"),ul=$("netUpLatency"),isp=$("netIsp"),srv=$("netServer"),loc=$("netLocation");if(jitter)jitter.textContent=d.jitterMs??"--";if(dl)dl.textContent=d.downloadLatencyMs??"--";if(ul)ul.textContent=d.uploadLatencyMs??"--";if(isp)isp.textContent=d.isp||"--";if(srv)srv.textContent=d.server?.name||"--";if(loc)loc.textContent=[d.server?.location,d.server?.country].filter(Boolean).join(", ")||"--";if(state){state.textContent="● COMPLETADO";state.classList.remove("measuring")}b.textContent="↻ MEDIR NUEVAMENTE"}catch(err){dn?.classList.remove("sweeping");un?.classList.remove("waiting");if(state){state.textContent="● ERROR";state.classList.remove("measuring")}b.textContent="↻ REINTENTAR";alert("No se pudo medir Internet: "+err.message)}finally{document.querySelector(".jr-speed-pro")?.classList.remove("is-testing");b.disabled=false}});
$("opsV2Content")?.addEventListener("click",async e=>{const set=e.target.closest("[data-net-limit]"),custom=e.target.closest("[data-net-custom]"),clear=e.target.closest("[data-net-clear]");if(!set&&!custom&&!clear)return;let mbps=set?Number(set.dataset.netLimit):null;if(custom){const value=prompt("Límite de salida en Mbps (1 a 10000):","30");if(value===null)return;mbps=Number(value);if(!Number.isFinite(mbps)||mbps<1||mbps>10000)return alert("Ingresá un valor entre 1 y 10000 Mbps.");mbps=Math.round(mbps)}const action=clear?"clear":"set";if(!confirm(action==="set"?`¿Limitar la SALIDA del servidor a ${mbps} Mbps?`:"¿Quitar el límite de ancho de banda del servidor?"))return;try{const r=await fetch("/api/network/limit",{method:"POST",headers:{"content-type":"application/json","x-csrf-token":csrfToken},body:JSON.stringify({action,mbps})}),d=await r.json();if(!r.ok)throw Error(d.error||d.output||"network_limit_failed");alert(action==="set"?`Límite de salida aplicado: ${mbps} Mbps.`:"Límite eliminado.");loadOpsV2("network")}catch(err){alert("No se pudo cambiar el límite de red: "+err.message)}});
